import XCTest
@testable import VNCPrivacyCore

final class VNCSessionMonitorTests: XCTestCase {
    func testPollOnceEmitsOnlyEffectiveStateChanges() async throws { let established = TCPConnectionRecord(state: .established, localAddress: "192.168.1.10", localPort: 5900, remoteAddress: "100.64.1.5", remotePort: 50000); let provider = QueueTCPProvider(results: [.success([established]),.success([established]),.success([]),.success([])]); let monitor = VNCSessionMonitor(provider: provider, disconnectDebounce: 2.0); let t0 = Date(timeIntervalSince1970: 1_000); let first = await monitor.pollOnce(now: t0); let duplicate = await monitor.pollOnce(now: t0.addingTimeInterval(0.5)); let debouncing = await monitor.pollOnce(now: t0.addingTimeInterval(1.0)); let disconnected = await monitor.pollOnce(now: t0.addingTimeInterval(3.1)); XCTAssertEqual(first?.state, .connected); XCTAssertNil(duplicate); XCTAssertEqual(debouncing?.isDisconnectDebouncing, true); XCTAssertEqual(disconnected?.state, .disconnected) }
    func testProviderFailureEmitsUncertainWithoutDroppingSession() async { let established = TCPConnectionRecord(state: .established, localAddress: "192.168.1.10", localPort: 5900, remoteAddress: "10.0.0.2", remotePort: 50000); let monitor = VNCSessionMonitor(provider: QueueTCPProvider(results: [.success([established]),.failure(TCPConnectionProviderError.unavailable("temporary"))])); _ = await monitor.pollOnce(now: Date(timeIntervalSince1970: 2_000)); let uncertain = await monitor.pollOnce(now: Date(timeIntervalSince1970: 2_001)); XCTAssertEqual(uncertain?.state, .uncertain); XCTAssertEqual(uncertain?.activeConnections.count, 1); XCTAssertEqual(uncertain?.shouldProtect, true) }
}
private actor QueueTCPProvider: TCPConnectionProviding { private var results: [Result<[TCPConnectionRecord], Error>]; init(results: [Result<[TCPConnectionRecord], Error>]) { self.results = results }; func snapshot() async throws -> [TCPConnectionRecord] { guard !results.isEmpty else { return [] }; return try results.removeFirst().get() } }
